('cso-national-coalition-for-natural-farming-ncnf-8b120d2a', 'National Coalition for Natural Farming (NCNF)', 'The National Coalition for Natural Farming is a collaborative platform for accelerating the spread of agroecology-based farming practices in its multiple variants, improving on existing practices, and collaborating for policy discourse.', 'The National Coalition for Natural Farming is a collaborative platform for accelerating the spread of agroecology-based farming practices in its multiple variants, improving on existing practices, and collaborating for policy discourse.', 'Pan-India, India', null, null, null, 'India', 'daniel@agroecologyfund.org', '2024-05-13 11', 'http://nfcoalition.in', '{}'::jsonb, '[]'::jsonb, ARRAY['Agroecology', 'Sustainable Agriculture', 'Policy Advocacy', 'Pan-India', 'India', 'Networks/Alliances', 'CRA Partner Map workbook']::text[], ARRAY['Agroecology', 'Sustainable Agriculture', 'Policy Advocacy', 'Pan-India', 'India', 'Networks/Alliances', 'National Coalition for Natural Farming (NCNF)']::text[], 22.3511148, 78.6677428, 'CRA Partner Map workbook', 'http://nfcoalition.in', '{"areas_of_work": ["Agroecology", "Sustainable Agriculture", "Policy Advocacy"], "beneficiary_groups": [], "geography_served": ["Pan-India", "India"], "registration_status": null, "registration_number": null, "programs": "The National Coalition for Natural Farming is a collaborative platform for accelerating the spread of agroecology-based farming practices in its multiple variants, improving on existing practices, and collaborating for policy discourse.", "volunteer_or_partner_needs": null}'::jsonb, 'CRA partner import', 'tanmay@greenruraleconomy.in', 'Source workbook category: Networks/Alliances
